import assert from 'node:assert/strict';
import { once } from 'node:events';
import { writeFile } from 'node:fs/promises';
import { setTimeout as delay } from 'node:timers/promises';
import { Relay } from '../clients/js/relay.mjs';

async function metrics() {
  const response = await fetch('http://127.0.0.1:1339/metrics');
  assert.equal(response.status, 200);
  return Object.fromEntries((await response.text()).split('\n').filter(line => line.startsWith('war_')).map(line => {
    const [name, value] = line.split(' '); return [name, Number(value)];
  }));
}
const result = { timestamp_utc: new Date().toISOString(), node: process.version, native_url: 'ws://127.0.0.1:1338' };
for (const path of ['healthz', 'readyz']) {
  const response = await fetch(`http://127.0.0.1:1339/${path}`);
  assert.equal(response.status, 200); result[path] = response.status;
}
const a = await Relay.connect(result.native_url, 'budget-live');
const b = await Relay.connect(result.native_url, 'budget-live');
try {
  const before = await metrics();
  assert.equal(before.war_read_buffer_limit_bytes, 1073741824);
  assert.equal(before.war_read_buffer_reserved_bytes, 16384);
  assert.equal(before.war_connections, 2);
  const unknown = [1n, 2n, 3n].find(id => id !== a.userId && id !== b.userId);
  a.send(unknown, new Uint8Array(4 * 1024 * 1024));
  assert.deepEqual(await a.getVariable('live-barrier'), { found: false, value: null });
  result.primed = await metrics();
  assert.ok(result.primed.war_read_buffer_reserved_bytes > before.war_read_buffer_reserved_bytes);
  assert.ok(result.primed.war_read_buffer_peak_reserved_bytes <= before.war_read_buffer_limit_bytes);
  const started = performance.now();
  let observed;
  do {
    observed = await metrics();
    if (observed.war_read_buffer_reclaims_total > before.war_read_buffer_reclaims_total) break;
    assert.ok(performance.now() - started < 9000, 'default read-buffer reclamation deadline');
    await delay(50);
  } while (true);
  result.reclaim_observed_seconds = (performance.now() - started) / 1000;
  result.after_reclaim = observed;
  assert.equal(observed.war_read_buffer_reserved_bytes, 16384);
  assert.equal(observed.war_connections, 2);
  assert.equal(observed.war_sessions, 2);
  assert.equal(observed.war_read_buffer_reclaim_header_bytes_total, 0);
  const copied = observed.war_routing_copied_bytes_total;
  const expected = { kind: 'after-reclaim', bytes: new Uint8Array([1, 2, 255]), wide: 0xfedcba9876543210n };
  const received = once(b, 'message');
  a.send(b.userId, expected);
  const event = (await received)[0];
  assert.equal(event.detail.sender, a.userId);
  assert.deepEqual(event.detail.value, expected);
  const after = await metrics();
  assert.equal(after.war_routing_copied_bytes_total, copied);
  assert.ok(after.war_routing_reused_bytes_total > observed.war_routing_reused_bytes_total);
  result.typed_routing_after_reclaim = true;
  result.extra_routed_body_copies = after.war_routing_copied_bytes_total - copied;
  const closed = [once(a, 'close'), once(b, 'close')];
  a.close(); b.close();
  for (const events of await Promise.all(closed)) assert.equal(events[0].detail.code, 1000);
  const stopped = performance.now();
  do {
    result.final_metrics = await metrics();
    if (['war_connections', 'war_sessions', 'war_queued_bytes', 'war_variable_bytes', 'war_read_buffer_reserved_bytes'].every(key => result.final_metrics[key] === 0)) break;
    assert.ok(performance.now() - stopped < 3000, 'live cleanup deadline');
    await delay(20);
  } while (true);
  for (const key of ['war_protocol_errors_total', 'war_write_errors_total', 'war_write_timeouts_total', 'war_close_failures_total', 'war_transport_disconnects_total', 'war_read_buffer_reservations_rejected_total']) assert.equal(result.final_metrics[key], 0);
  result.passed = true;
  await writeFile('docs/benchmarks/2026-10-16-fragment-final-live.json', JSON.stringify(result, null, 2) + '\n');
  console.log(JSON.stringify({ passed: true, reclaim_observed_seconds: result.reclaim_observed_seconds, extra_routed_body_copies: result.extra_routed_body_copies }));
} finally { a.close(); b.close(); }
